-- Brickpilot central drive DB production schema (PostgreSQL 16+)
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hosts(id bigserial PRIMARY KEY, hostname text NOT NULL, username text, role text, last_seen_at timestamptz, UNIQUE(hostname, username));
CREATE TABLE IF NOT EXISTS tools(id bigserial PRIMARY KEY, name text NOT NULL, version text, git_branch text, git_commit text, dirty boolean DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(name, version, git_branch, git_commit, dirty));
CREATE TABLE IF NOT EXISTS routes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id text NOT NULL, canonical_name text, route_label text, dongle_id text, device_serial text, source_device_route_key text, source_device text, vehicle text, branch text, brickpilot_version text, model_bundle text, drive_type text, started_at timestamptz, ended_at timestamptz, duration_sec double precision, segment_count integer DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), metadata_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(source_device_route_key), UNIQUE(source_device, route_id));
CREATE INDEX IF NOT EXISTS routes_route_id_idx ON routes(route_id);
CREATE TABLE IF NOT EXISTS route_segments(id bigserial PRIMARY KEY, route_uuid uuid NOT NULL REFERENCES routes(id) ON DELETE CASCADE, segment_index integer NOT NULL, started_at timestamptz, duration_sec double precision, has_qlog boolean DEFAULT false, has_rlog boolean DEFAULT false, has_qcamera boolean DEFAULT false, has_fcamera boolean DEFAULT false, has_ecamera boolean DEFAULT false, metadata_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(route_uuid, segment_index));
CREATE TABLE IF NOT EXISTS route_timebases(route_uuid uuid NOT NULL REFERENCES routes(id) ON DELETE CASCADE, monotonic_start_sec double precision, wall_start_at timestamptz, wall_end_at timestamptz, source text, timezone text, confidence double precision, raw_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY(route_uuid, source));
CREATE TABLE IF NOT EXISTS artifacts(id bigserial PRIMARY KEY, sha256 text NOT NULL UNIQUE, kind text NOT NULL, mime_type text, size_bytes bigint NOT NULL, artifact_path text NOT NULL, original_path text, source_host_id bigint REFERENCES hosts(id), copy_status text NOT NULL DEFAULT 'verified', verified_at timestamptz, sha256_verified boolean NOT NULL DEFAULT false, imported_at timestamptz NOT NULL DEFAULT now(), metadata_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS source_paths(artifact_id bigint NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, host_id bigint NOT NULL REFERENCES hosts(id), path text NOT NULL, mtime timestamptz, size_bytes bigint, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), UNIQUE(host_id, path));
CREATE TABLE IF NOT EXISTS route_artifacts(route_uuid uuid NOT NULL REFERENCES routes(id) ON DELETE CASCADE, segment_id bigint REFERENCES route_segments(id) ON DELETE CASCADE, artifact_id bigint NOT NULL REFERENCES artifacts(id), role text NOT NULL, start_sec double precision, duration_sec double precision);
CREATE UNIQUE INDEX IF NOT EXISTS route_artifacts_segment_uq ON route_artifacts(route_uuid, segment_id, artifact_id, role) WHERE segment_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS route_artifacts_route_uq ON route_artifacts(route_uuid, artifact_id, role) WHERE segment_id IS NULL;
CREATE TABLE IF NOT EXISTS video_sync_segments(id bigserial PRIMARY KEY, route_uuid uuid NOT NULL REFERENCES routes(id) ON DELETE CASCADE, artifact_id bigint NOT NULL REFERENCES artifacts(id), segment_index integer, route_start_sec double precision, video_start_sec double precision, duration_sec double precision, source_path text, confidence double precision, raw_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(route_uuid, artifact_id, segment_index));
CREATE TABLE IF NOT EXISTS ingest_runs(id bigserial PRIMARY KEY, source_host text, source_root text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status text NOT NULL DEFAULT 'running', tool_id bigint REFERENCES tools(id), selected_route_ids text[], summary_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, error text);
CREATE TABLE IF NOT EXISTS ingest_items(id bigserial PRIMARY KEY, ingest_run_id bigint REFERENCES ingest_runs(id) ON DELETE CASCADE, route_uuid uuid REFERENCES routes(id), artifact_id bigint REFERENCES artifacts(id), action text, status text, message text);
CREATE TABLE IF NOT EXISTS legacy_files(id bigserial PRIMARY KEY, artifact_id bigint REFERENCES artifacts(id), source_path text, parser_status text, counts_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, warnings_jsonb jsonb NOT NULL DEFAULT '[]'::jsonb, UNIQUE(source_path));
CREATE TABLE IF NOT EXISTS migration_runs(id bigserial PRIMARY KEY, name text, source_host text, source_root text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status text, stats_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, warnings_jsonb jsonb NOT NULL DEFAULT '[]'::jsonb);
CREATE TABLE IF NOT EXISTS route_samples(route_uuid uuid REFERENCES routes(id) ON DELETE CASCADE, t_sec double precision NOT NULL, speed_mph double precision, set_speed_mph double precision, a_ego_mps2 double precision, gas_pressed boolean, brake_pressed boolean, lead_status boolean, lead_d_rel_m double precision, lead_v_rel_mps double precision, raw_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY(route_uuid,t_sec));
CREATE TABLE IF NOT EXISTS can_frames_sampled(route_uuid uuid REFERENCES routes(id) ON DELETE CASCADE, t_sec double precision NOT NULL, bus integer, address integer, data_hex text, name text, hint text, is_unknown boolean, raw_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS can_frames_sampled_route_time_idx ON can_frames_sampled(route_uuid, t_sec);
CREATE TABLE IF NOT EXISTS events(id bigserial PRIMARY KEY, route_uuid uuid REFERENCES routes(id) ON DELETE CASCADE, source text, event_type text, t_sec double precision, end_t_sec double precision, severity text, summary text, raw_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS input_sets(id bigserial PRIMARY KEY, name text, fingerprint text NOT NULL UNIQUE, tool_id bigint REFERENCES tools(id), params_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS input_set_members(input_set_id bigint REFERENCES input_sets(id) ON DELETE CASCADE, route_uuid uuid REFERENCES routes(id), artifact_id bigint REFERENCES artifacts(id), label_id bigint, label_version integer, role text, metadata_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS analysis_runs(id bigserial PRIMARY KEY, route_uuid uuid REFERENCES routes(id), input_set_id bigint REFERENCES input_sets(id), analysis_name text, tool_id bigint REFERENCES tools(id), started_at timestamptz, finished_at timestamptz, status text, params_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, summary_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, report_artifact_id bigint REFERENCES artifacts(id), created_by text);
CREATE TABLE IF NOT EXISTS analysis_outputs(analysis_run_id bigint REFERENCES analysis_runs(id) ON DELETE CASCADE, artifact_id bigint REFERENCES artifacts(id), role text, metadata_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS ml_runs(id bigserial PRIMARY KEY, name text, input_set_id bigint REFERENCES input_sets(id), tool_id bigint REFERENCES tools(id), started_at timestamptz, finished_at timestamptz, status text, params_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, summary_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS ml_run_outputs(ml_run_id bigint REFERENCES ml_runs(id) ON DELETE CASCADE, artifact_id bigint REFERENCES artifacts(id), role text, metadata_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS review_inboxes(id bigserial PRIMARY KEY, name text UNIQUE NOT NULL, purpose text, created_at timestamptz NOT NULL DEFAULT now(), tool_id bigint REFERENCES tools(id), query_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, metadata_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS review_jobs(id bigserial PRIMARY KEY, inbox_id bigint REFERENCES review_inboxes(id) ON DELETE CASCADE, route_uuid uuid REFERENCES routes(id), legacy_job_id text, status text NOT NULL DEFAULT 'pending', selected boolean, ride_type text, route_label text, sort_order integer, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), updated_by text);
CREATE UNIQUE INDEX IF NOT EXISTS review_jobs_legacy_uq ON review_jobs(inbox_id, route_uuid, legacy_job_id) WHERE legacy_job_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS review_jobs_route_null_legacy_uq ON review_jobs(inbox_id, route_uuid) WHERE legacy_job_id IS NULL;
CREATE TABLE IF NOT EXISTS labels(id bigserial PRIMARY KEY, route_uuid uuid REFERENCES routes(id), review_job_id bigint REFERENCES review_jobs(id), label_identity_hash text UNIQUE, label_kind text, label text, severity text, start_sec double precision, end_sec double precision, notes text, tags text[], version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by text, updated_by text, deleted_at timestamptz, deleted_by text, metadata_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS label_events(id bigserial PRIMARY KEY, label_id bigint REFERENCES labels(id), review_job_id bigint REFERENCES review_jobs(id), action text, payload_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), created_by text);
CREATE TABLE IF NOT EXISTS bookmarks(id bigserial PRIMARY KEY, route_uuid uuid REFERENCES routes(id), bookmark_identity_hash text UNIQUE, source text, t_sec double precision, end_sec double precision, text text, tags text[], artifact_id bigint REFERENCES artifacts(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), updated_by text, deleted_at timestamptz, deleted_by text, metadata_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS finished_reviews(id bigserial PRIMARY KEY, review_job_id bigint REFERENCES review_jobs(id), route_uuid uuid REFERENCES routes(id), finished_at timestamptz NOT NULL DEFAULT now(), finished_by text, label_count integer, notes text, snapshot_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb);

INSERT INTO schema_migrations(version) VALUES('001_initial_postgres') ON CONFLICT(version) DO NOTHING;
